package storage_test
import("bytes";"context";"crypto/sha256";"encoding/hex";"os";"path/filepath";"testing";"github.com/kzs0/reviewd/internal/storage")
func TestArtifactsDeclarative(t *testing.T){ctx:=context.Background();s,e:=storage.Open(t.TempDir());if e!=nil{t.Fatal(e)};defer s.Close();for _,payload:=range [][]byte{nil,[]byte("source\n"),[]byte{0,255,1}}{d,e:=s.Put(ctx,payload);if e!=nil{t.Fatal(e)};sum:=sha256.Sum256(payload);if d!=hex.EncodeToString(sum[:]){t.Fatalf("wrong digest %s",d)};got,e:=s.Get(ctx,d);if e!=nil||!bytes.Equal(got,payload){t.Fatalf("round trip %q %v",got,e)};d2,e:=s.Put(ctx,payload);if e!=nil||d2!=d{t.Fatal("not idempotent")}};for _,d:=range []string{"../state.db","", "aaa",string(bytes.Repeat([]byte("g"),64))}{if _,e:=s.Get(ctx,d);e==nil{t.Fatalf("accepted digest %q",d)}}}
func TestDurableRecordsAndSQLite(t *testing.T){ctx:=context.Background();root:=t.TempDir();s,e:=storage.Open(root);if e!=nil{t.Fatal(e)};if e=s.Save(ctx,"review","one",[]byte("first"));e!=nil{t.Fatal(e)};if e=s.Save(ctx,"review","one",[]byte("updated"));e!=nil{t.Fatal(e)};s.Close();b,e:=os.ReadFile(filepath.Join(root,"state.db"));if e!=nil||!bytes.HasPrefix(b,[]byte("SQLite format 3\x00")){t.Fatalf("not SQLite: %v",e)};s,e=storage.Open(root);if e!=nil{t.Fatal(e)};defer s.Close();got,e:=s.Load(ctx,"review","one");if e!=nil||string(got)!="updated"{t.Fatalf("not durable %q %v",got,e)};if _,e=s.Load(ctx,"release","one");e==nil{t.Fatal("record namespaces not isolated")}}
func TestStorageCancellation(t *testing.T){s,e:=storage.Open(t.TempDir());if e!=nil{t.Fatal(e)};defer s.Close();ctx,cancel:=context.WithCancel(context.Background());cancel();if _,e=s.Put(ctx,[]byte("x"));e==nil{t.Fatal("canceled artifact write succeeded")};if e=s.Save(ctx,"x","x",nil);e==nil{t.Fatal("canceled db write succeeded")}}
